cat > .local/smart-shorts-seven/watch-browser-memory.mjs <<'EOF'
import {execFileSync} from 'node:child_process';import {readFileSync,writeFileSync} from 'node:fs';
const baseline=new Set(JSON.parse(readFileSync('.local/smart-shorts-seven/browser-baseline-pids.json')));
const rows=()=>execFileSync('ps',['-axo','pid,rss,comm'],{encoding:'utf8'}).split('\n').filter(l=>l.includes('Google Chrome Helper (Renderer)')).map(l=>{const [pid,rss]=l.trim().split(/\s+/);return {pid:+pid,rss:+rss*1024}});
const targets=rows().filter(r=>!baseline.has(r.pid)).map(r=>r.pid);console.log({targets});
const measurements=[];let peak=0,last=-1;const began=Date.now();
const sample=()=>{const live=rows().filter(r=>targets.includes(r.pid));const rss=live.reduce((sum,r)=>sum+r.rss,0);peak=Math.max(peak,rss);measurements.push({at:new Date().toISOString(),rss,live});if(Math.abs(rss-last)>64*1024**2||!live.length){console.log({rss,peak,live});last=rss;}writeFileSync('.local/smart-shorts-seven/browser-memory-measurements.json',JSON.stringify({targets,peak,measurements}));if(Date.now()-began>3600000||!live.length){clearInterval(timer);console.log('Stopped memory observer');}};
const timer=setInterval(sample,5000);sample();
EOF
node .local/smart-shorts-seven/watch-browser-memory.mjs > .local/smart-shorts-seven/browser-memory-watch.log 2>&1
